'use strict';
const KEY='chabak-packing-wf-v1';
const clone=x=>JSON.parse(JSON.stringify(x));
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const defaults=[['기본','배낭','등산화'],['의류·보온','바람막이','보온 재킷','장갑','모자'],['식량','식수','행동식'],['야영','텐트','침낭','랜턴'],['기타 등산장비','등산스틱','아이젠']].map(([name,...names],order)=>({id:uid(),name,builtin:true,order,items:names.map(name=>({id:uid(),name,selected:true,done:false}))}));
let db={base:defaults,lists:[]};let storageError=false;
try{const raw=localStorage.getItem(KEY);if(raw){const value=JSON.parse(raw);if(!Array.isArray(value.base)||!Array.isArray(value.lists))throw Error();db=value;}}catch{storageError=true;}
let mode='home',draft=null,dirty=false,dragged=null,toastTimer;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));return true;}catch{toast('저장 공간이 부족하거나 저장이 차단됐어요. 현재 화면에서만 유지돼요.');return false;}}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',4000);}
const groups=()=>draft.groups;
const stats=gs=>{const items=gs.flatMap(g=>g.items);return{total:items.length,done:items.filter(i=>i.done).length};};
const progress=gs=>{const s=stats(gs),pct=s.total?Math.round(s.done/s.total*100):0;return `<div class="progress-label"><span>${s.done===s.total&&s.total?'준비 완료':'챙긴 준비물'} <b>${s.done} / ${s.total}개</b></span><b>${pct}%</b></div><progress value="${s.done}" max="${s.total||1}" aria-label="준비 완료 ${pct}%"></progress>`;};
const dateLabel=d=>d?`${Number(d.slice(5,7))}/${Number(d.slice(8,10))}`:'';
function saveDetail(){if(mode==='detail'){db.lists=db.lists.map(l=>l.id===draft.id?clone(draft):l);persist();}}
function changed(){dirty=true;saveDetail();render();}
function header(title){return `<header><div class="app-bar__leading">${mode!=='home'?'<button class="app-bar__icon" data-action="back" aria-label="뒤로가기"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button>':'<a class="app-bar__icon" href="home.html" aria-label="뒤로가기"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></a>'}<strong>준비물</strong></div><div class="app-bar__actions"><a class="app-bar__icon" href="community.html#/notifications" aria-label="알림센터"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4"/></svg></a><a class="app-bar__icon" href="community.html#/search" aria-label="검색"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 20l-4-4 M18 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0"/></svg></a></div></header><h1>${title}</h1>`;}
function render(){
if(mode==='home'){app.innerHTML=header('산행을 준비해 볼까요?')+`<p class="muted">챙길 것들을 한곳에, 다음 산행에도 간편하게.</p><div class="stack"><button class="primary" data-action="new">＋ 체크리스트 만들기</button><button data-action="base">내 기본 준비물 편집</button></div><div class="section-head"><h2>내 체크리스트</h2><span class="muted">${db.lists.length}개</span></div>`+(db.lists.length?db.lists.map(l=>`<article class="card"><div class="card-title"><h2>${esc(l.title)}</h2><button class="menu" data-action="list-menu" data-id="${l.id}" aria-label="${esc(l.title)} 메뉴">⋯</button></div><small>${esc(l.date.replaceAll('-','.'))}</small>${progress(l.groups)}<div class="actions"><button class="primary" data-action="open" data-id="${l.id}">열기</button><button data-action="copy" data-id="${l.id}">복사해서 새로 만들기</button></div></article>`).join(''):'<div class="data-empty"><div class="edge-state__icon edge-state__icon--mountain" aria-hidden="true"></div><p class="edge-state__description">아직 준비한 산행이 없어요<br>첫 체크리스트를 만들어 보세요</p></div>')+'<p class="muted">이 브라우저에 자동 저장돼요. 다른 기기와는 동기화되지 않아요.</p>';return;}
const isBase=mode==='base',isNew=mode==='new';
app.innerHTML=header(isBase?'내 기본 준비물 편집':isNew?'새 체크리스트':esc(draft.title))+(isBase?'<p class="notice">앞으로 만들 목록의 기본 구성이에요.<br>이미 저장된 체크리스트는 바뀌지 않아요.</p>':isNew?`<label class="field"><span>산행 날짜</span><input id="trip-date" type="date" value="${esc(draft.date)}" required></label><label class="field"><span>제목 <small class="muted">선택</small></span><input id="trip-title" maxlength="60" placeholder="예: 북한산 당일 산행" value="${esc(draft.title)}"></label><div class="section-head"><h2>가져갈 준비물 선택</h2></div><p class="notice">변경 내용은 이번 산행에만 적용돼요.</p>`:`<div class="card-title"><p class="muted">${esc(draft.date.replaceAll('-','.'))}</p><button data-action="trip-edit">날짜·제목 수정</button></div>${progress(groups())}<p class="muted">챙긴 물건에 체크하세요.</p>`)+(!isBase?'<p class="drag-hint">⋯ 메뉴에서 수정·이동할 수 있어요.</p>':'')+renderGroups()+`<div class="actions"><button data-action="add-group">＋ 새 카테고리</button><button data-action="add-item">＋ 새 항목</button></div>`+(isBase?'<div class="sticky"><button class="primary wide" data-action="save-base">기본 준비물 저장</button></div>':isNew?`<div class="sticky"><button class="primary wide" data-action="create" ${selectedCount()?'':'disabled'}>선택한 ${selectedCount()}개로 만들기</button></div>`:'<p class="notice" style="margin-top:20px">수정은 이 체크리스트에만 적용돼요.<br>기본 목록에도 넣으려면 ⋯ → 다음 산행에도 사용</p>');
app.querySelectorAll('[data-parent]').forEach(el=>{const g=groups().find(g=>g.id===el.dataset.parent);const count=g.items.filter(i=>i.selected).length;el.indeterminate=count>0&&count<g.items.length;});
}
function selectedCount(){return groups().flatMap(g=>g.items).filter(i=>i.selected).length;}
function renderGroups(){return groups().map(g=>{const n=g.items.filter(i=>i.selected).length;return `<section class="group" data-group="${g.id}"><div class="group-head">${mode==='new'?`<label><input type="checkbox" data-parent="${g.id}" ${g.items.length&&n===g.items.length?'checked':''}>${esc(g.name)}<small>${n}/${g.items.length}</small></label>`:`<h2 style="flex:1">${esc(g.name)}</h2>`}<button class="menu" data-action="group-menu" data-g="${g.id}" aria-label="${esc(g.name)} 카테고리 메뉴">⋯</button></div>${g.items.map(i=>`<div class="item ${mode==='detail'&&i.done?'done':''}" draggable="true" data-g="${g.id}" data-i="${i.id}">${mode==='base'?`<span class="item-name">${esc(i.name)}</span>`:`<label><input type="checkbox" data-item="${i.id}" data-g="${g.id}" ${(mode==='new'?i.selected:i.done)?'checked':''}><span class="item-name">${esc(i.name)}</span></label>`}<button class="menu" data-action="item-menu" data-g="${g.id}" data-i="${i.id}" aria-label="${esc(i.name)} 항목 메뉴">⋯</button></div>`).join('')}<button class="add" data-action="add-item" data-g="${g.id}">＋ 새 항목 추가</button></section>`;}).join('')||'<div class="data-empty"><div class="edge-state__icon edge-state__icon--mountain" aria-hidden="true"></div><p class="edge-state__description">카테고리를 추가해 준비물을 넣어 보세요</p></div>';}
function showDialog(title,body,onSubmit){dialog.dataset.risky=String(['삭제할까요?','체크리스트 삭제','변경 내용을 나갈까요?'].includes(title));dialog.innerHTML=`<form><h2>${esc(title)}</h2>${body}<div class="actions"><button type="button" data-close>취소</button>${onSubmit?'<button class="primary" type="submit">확인</button>':''}</div></form>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();if(onSubmit)onSubmit(new FormData(e.target));};window.prepareDialogActions(dialog);dialog.showModal();}
function nameField(value='',label='이름'){return `<label class="field"><span>${label}</span><input name="name" value="${esc(value)}" required maxlength="60" autofocus></label>`;}
function groupOptions(selected){return `<label class="field"><span>넣을 카테고리</span><select name="group">${groups().map(g=>`<option value="${g.id}" ${g.id===selected?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>`;}
function textValue(fd){const n=String(fd.get('name')||'').trim();if(!n){toast('이름을 입력해 주세요.');return null;}return n;}
function itemAdd(gid){if(!groups().length){toast('먼저 카테고리를 만들어 주세요.');addGroup();return;}showDialog('새 준비물 추가',nameField('','준비물 이름')+groupOptions(gid),fd=>{const name=textValue(fd);if(!name)return;const g=groups().find(g=>g.id===fd.get('group'));if(g.items.some(i=>i.name===name)){toast('같은 이름의 준비물이 이미 있어요.');return;}g.items.push({id:uid(),name,selected:true,done:false});dialog.close();changed();toast(mode==='base'?'기본 목록에 추가했어요. 저장 버튼을 눌러 주세요.':'이번 산행에 추가했어요.');});}
function addGroup(){showDialog('새 카테고리',nameField('','카테고리 이름'),fd=>{const name=textValue(fd);if(!name)return;if(groups().some(g=>g.name===name)){toast('같은 카테고리가 이미 있어요.');return;}groups().push({id:uid(),name,builtin:false,items:[]});dialog.close();changed();});}
function move(gid,iid,target){if(gid===target)return;const from=groups().find(g=>g.id===gid),to=groups().find(g=>g.id===target),i=from.items.find(i=>i.id===iid);if(to.items.some(x=>x.name===i.name)){toast('이 카테고리에 같은 준비물이 있어요.');return;}from.items=from.items.filter(x=>x.id!==iid);to.items.push(i);changed();toast(`${to.name}(으)로 옮겼어요.`);}
function addToBase(g,i){let target=db.base.find(x=>x.id===g.id)||db.base.find(x=>x.name===g.name);if(!target){target={id:g.id,name:g.name,builtin:false,items:[]};db.base.push(target);}let count=0;for(const item of i?[i]:g.items){if(!target.items.some(x=>x.id===item.id||x.name===item.name)){target.items.push({...clone(item),selected:true,done:false});count++;}}const ok=persist();if(ok)toast(count?'내 기본 준비물에도 추가했어요.':'이미 기본 준비물에 있어요.');}
function menu(gid,iid){const g=groups().find(g=>g.id===gid),i=iid?g.items.find(i=>i.id===iid):null;showDialog(i?i.name:g.name,`<div class="stack"><button type="button" data-menu="rename">이름 수정하기</button>${i?'<button type="button" data-menu="move">다른 카테고리로 이동</button>':''}<button type="button" data-menu="delete">삭제하기</button>${mode==='detail'?'<button type="button" data-menu="base">다음 산행에도 사용</button>':''}</div>`);dialog.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>{dialog.close();const action=b.dataset.menu;if(action==='base'){addToBase(g,i);return;}if(action==='rename'){showDialog('이름 수정',nameField((i||g).name),fd=>{const name=textValue(fd);if(!name)return;const siblings=i?g.items:groups();if(siblings.some(x=>x!==(i||g)&&x.name===name)){toast('같은 이름이 이미 있어요.');return;}(i||g).name=name;dialog.close();changed();});}if(action==='move'){showDialog('다른 카테고리로 이동',groupOptions(gid),fd=>{dialog.close();move(gid,iid,fd.get('group'));});}if(action==='delete'){showDialog('삭제할까요?',`<p>${esc((i||g).name)}${i?'':'과(와) 하위 준비물'}을 ${mode==='base'?'기본 목록':'이번 목록'}에서 삭제해요.</p>`,()=>{if(i)g.items=g.items.filter(x=>x.id!==iid);else draft.groups=groups().filter(x=>x.id!==gid);dialog.close();changed();});}});}
function leave(){if((mode==='base'||mode==='new')&&dirty){showDialog('변경 내용을 나갈까요?', '<p>저장하지 않은 변경 내용은 사라져요.</p>',()=>{dialog.close();mode='home';draft=null;dirty=false;render();});}else{mode='home';draft=null;dirty=false;render();}}
function startNew(source){mode='new';draft={id:uid(),title:source?source.title:'',date:today(),groups:clone(source?source.groups:db.base)};draft.groups.forEach(g=>g.items.forEach(i=>{i.done=false;i.selected=true;}));dirty=false;render();window.scrollTo(0,0);}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,g,i}=b.dataset;
if(action==='new')startNew();if(action==='base'){mode='base';draft={groups:clone(db.base)};dirty=false;render();window.scrollTo(0,0);}if(action==='back')leave();if(action==='copy')startNew(db.lists.find(l=>l.id===id));if(action==='open'){mode='detail';draft=clone(db.lists.find(l=>l.id===id));dirty=false;render();window.scrollTo(0,0);}if(action==='add-group')addGroup();if(action==='add-item')itemAdd(g);if(action==='group-menu'||action==='item-menu')menu(g,i);
if(action==='save-base'){db.base=clone(groups());const ok=persist();dirty=false;mode='home';render();if(ok)toast('기본 준비물을 저장했어요. 다음 목록부터 적용돼요.');}
if(action==='create'){const date=document.querySelector('#trip-date');if(!date.reportValidity())return;if(!selectedCount())return;draft.date=date.value;draft.title=document.querySelector('#trip-title').value.trim()||`${dateLabel(draft.date)} 산행 준비물`;draft.groups=groups().map(g=>({...g,items:g.items.filter(i=>i.selected).map(i=>({...i,done:false}))})).filter(g=>g.items.length);db.lists.unshift(clone(draft));persist();mode='detail';dirty=false;render();window.scrollTo(0,0);}
if(action==='trip-edit'){showDialog('산행 정보 수정',`<label class="field"><span>날짜</span><input name="date" type="date" required value="${draft.date}"></label>`+nameField(draft.title,'제목'),fd=>{const name=textValue(fd);if(!name)return;draft.date=fd.get('date');draft.title=name;dialog.close();changed();});}
if(action==='list-menu'){const l=db.lists.find(l=>l.id===id);showDialog('체크리스트 삭제',`<p>‘${esc(l.title)}’ 목록을 삭제할까요?</p>`,()=>{db.lists=db.lists.filter(l=>l.id!==id);persist();dialog.close();render();});}
});
app.addEventListener('input',e=>{if(e.target.id==='trip-title'){draft.title=e.target.value;dirty=true;}if(e.target.id==='trip-date'){draft.date=e.target.value;dirty=true;}});
app.addEventListener('change',e=>{const t=e.target;if(t.dataset.parent){groups().find(g=>g.id===t.dataset.parent).items.forEach(i=>i.selected=t.checked);changed();}if(t.dataset.item){const i=groups().find(g=>g.id===t.dataset.g).items.find(i=>i.id===t.dataset.item);i[mode==='new'?'selected':'done']=t.checked;changed();}});
app.addEventListener('dragstart',e=>{const row=e.target.closest('[data-i].item');if(!row)return;dragged={g:row.dataset.g,i:row.dataset.i};e.dataTransfer.setData('text/plain',row.dataset.i);});
app.addEventListener('dragover',e=>{const group=e.target.closest('[data-group]');if(group&&dragged){e.preventDefault();group.classList.add('drop');}});
app.addEventListener('dragleave',e=>{const group=e.target.closest('[data-group]');if(group&&!group.contains(e.relatedTarget))group.classList.remove('drop');});
app.addEventListener('drop',e=>{const group=e.target.closest('[data-group]');if(group&&dragged){e.preventDefault();move(dragged.g,dragged.i,group.dataset.group);}dragged=null;app.querySelectorAll('.drop').forEach(x=>x.classList.remove('drop'));});
app.addEventListener('dragend',()=>{dragged=null;app.querySelectorAll('.drop').forEach(x=>x.classList.remove('drop'));});
let holdTimer=null,held=false;
app.addEventListener('pointerdown',e=>{const row=e.target.closest('.item,.group-head');if(!row||e.target.closest('button,input'))return;held=false;holdTimer=setTimeout(()=>{held=true;const section=row.closest('[data-group]');menu(section.dataset.group,row.dataset.i);},650);});
for(const event of ['pointerup','pointercancel','pointermove','dragstart'])app.addEventListener(event,()=>clearTimeout(holdTimer));
app.addEventListener('click',e=>{if(held){e.preventDefault();e.stopPropagation();held=false;}},true);
window.addEventListener('beforeunload',e=>{if(dirty&&(mode==='base'||mode==='new')){e.preventDefault();e.returnValue='';}});
render();if(storageError)toast('저장된 데이터를 읽지 못했어요. 기본 목록으로 시작합니다.');
